using System.Collections.Generic;
using Godot;

namespace Gearheart.Core;

/// <summary>
/// Sound effects. One-shots are played by name; the engine and drill are loops whose pitch
/// and volume follow the car. Sounds are generated by tools/make_sounds.py.
/// </summary>
public partial class Sfx : Node
{
    private const int LoopFrames = 22050;   // engine, drill, boost and wind loops are exactly one second

    private readonly Dictionary<string, AudioStream> _streams = new();
    private readonly List<AudioStreamPlayer> _voices = new();
    private readonly Dictionary<string, double> _lastPlayed = new();
    private AudioStreamPlayer _engine, _drill, _boost, _wind;
    private int _nextVoice;
    private double _time;

    public override void _Ready()
    {
        foreach (string name in new[] { "pick", "break", "place", "pickup", "thud", "crunch", "snap", "treasure", "fuel", "tally", "record", "land" })
            _streams[name] = GD.Load<AudioStream>($"res://assets/audio/{name}.wav");

        for (int i = 0; i < 6; i++)
        {
            var voice = new AudioStreamPlayer();
            AddChild(voice);
            _voices.Add(voice);
        }

        _engine = Loop("engine");
        _drill = Loop("drill");
        _boost = Loop("boost");
        _wind = Loop("wind");
    }

    private AudioStreamPlayer Loop(string name)
    {
        var stream = GD.Load<AudioStream>($"res://assets/audio/{name}.wav");
        if (stream is AudioStreamWav wav)
        {
            wav.LoopMode = AudioStreamWav.LoopModeEnum.Forward;
            wav.LoopBegin = 0;
            wav.LoopEnd = LoopFrames;
        }
        var player = new AudioStreamPlayer { Stream = stream, VolumeDb = -80f };
        AddChild(player);
        return player;
    }

    public override void _Process(double delta) => _time += delta;

    /// <summary>
    /// Plays a one-shot, at most once per <paramref name="minGap"/> seconds per sound.
    /// A <paramref name="pitch"/> of 0 picks a slightly random pitch.
    /// </summary>
    public void Play(string name, float volumeDb = -8f, float minGap = 0.05f, float pitch = 0f)
    {
        if (!_streams.TryGetValue(name, out var stream) || stream == null) return;
        if (_lastPlayed.TryGetValue(name, out double last) && _time - last < minGap) return;
        _lastPlayed[name] = _time;

        var voice = _voices[_nextVoice];
        _nextVoice = (_nextVoice + 1) % _voices.Count;
        voice.Stream = stream;
        voice.VolumeDb = volumeDb;
        voice.PitchScale = pitch > 0f ? pitch * (float)GD.RandRange(0.96, 1.04) : (float)GD.RandRange(0.9, 1.1);
        voice.Play();
    }

    /// <summary>Call every frame: engine pitch follows speed and throttle; the drill whirs while cutting.</summary>
    public void UpdateCar(bool driving, float speed, float throttle, bool drilling, bool boosting = false)
    {
        SetLoop(_boost, driving && boosting, -9f, 0.9f + Mathf.Min(0.4f, speed / 2500f));
        SetLoop(_engine, driving, -17f + 7f * Mathf.Abs(throttle), 0.75f + Mathf.Min(1.5f, speed / 380f) + 0.3f * Mathf.Abs(throttle));
        SetLoop(_drill, driving && drilling, -14f, 1f);

        // Wind rushing past: silent below about 30 km/h, a loud whoosh near top speed.
        float wind = Mathf.Clamp((speed / 64f * 3.6f - 30f) / 45f, 0f, 1f);
        WindLevel = wind;
        SetLoop(_wind, driving && wind > 0f, Mathf.LinearToDb(Mathf.Max(0.001f, wind)) - 9f, 0.8f + 0.5f * wind);
    }

    /// <summary>How loud the wind is, 0..1 (for the bot log).</summary>
    public float WindLevel { get; private set; }

    private static void SetLoop(AudioStreamPlayer player, bool on, float volumeDb, float pitch)
    {
        if (on)
        {
            player.VolumeDb = volumeDb;
            player.PitchScale = pitch;
            if (!player.Playing) player.Play();
        }
        else if (player.Playing)
        {
            player.Stop();
        }
    }
}
